  `owner` varchar(255) NOT NULL DEFAULT '' COMMENT 'A themeâ€™s â€™parentâ€™ . Can be either a theme or an engine.',
  `status` int NOT NULL DEFAULT '0' COMMENT 'Boolean indicating whether or not this item is enabled.',
  `bootstrap` int NOT NULL DEFAULT '0' COMMENT 'Boolean indicating whether this module is loaded during Backdropâ€™s early bootstrapping phase (e.g. even before the page cache is consulted).',
  `schema_version` smallint NOT NULL DEFAULT '-1' COMMENT 'The moduleâ€™s database schema version number. -1 if the module is not installed (its tables do not exist); 0 or the largest N of the moduleâ€™s hook_update_N() function that has either been run or existed when the module was first installed.',
  `weight` int NOT NULL DEFAULT '0' COMMENT 'The order in which this moduleâ€™s hooks should be invoked relative to other modules. Equal-weighted modules are ordered by name.',
  `info` blob COMMENT 'A serialized array containing information from the moduleâ€™s .info file; keys can include name, description, package, version, core, dependencies, and php.',
  PRIMARY KEY (`filename`),
